exec python3 -c "exec(\"import sys,json\\nfrom functools import reduce\\nG=lambda b:reduce(lambda n,v:n*257+v+1,b,1)\\ndef D(n):\\n b=[]\\n while n>1:\\n  n,r=divmod(n-1,257)\\n  if r>255:raise ValueError('code')\\n  b.append(r)\\n return bytes(b[::-1])\\ndef run(a,N):\\n assert type(N)==int and 0<=N<=100000\\n blank=a.get('blank','_');s=a['start'];h=a['halt'];w=a.get('input','');rules=a['rules']\\n assert type(blank)==str and len(blank)==1 and type(s)==str and isinstance(h,list) and all(isinstance(x,str) for x in h) and isinstance(w,str) and isinstance(rules,list)\\n d={}\\n for q,c,t,v,m in rules:\\n  assert all(isinstance(x,str) for x in (q,c,t,v)) and len(c)==len(v)==1 and type(m)==int and m in (-1,0,1) and (q,c) not in d\\n  d[q,c]=(t,v,m)\\n p=0;t={i:v for i,v in enumerate(w) if v!=blank};seen={};events=[];status='UNKNOWN';cycle=None;k=0\\n while k<=N:\\n  if s in h:status='HALTED';break\\n  key=(s,p,tuple(sorted(t.items())))\\n  if key in seen:status='PROVEN_NONHALTING';cycle=[seen[key],k];break\\n  if k==N:break\\n  seen[key]=k;c=t.get(p,blank);z=d.get((s,c))\\n  if z is None:status='HALTED';break\\n  q,v,m=z;pre=[s,p,sorted(t.items())]\\n  if v==blank:t.pop(p,None)\\n  else:t[p]=v\\n  s=q;p+=m;post=[s,p,sorted(t.items())]\\n  e={'step':k,'pre':pre,'read':c,'write':v,'move':m,'post':post}\\n  b=json.dumps(e,sort_keys=True,separators=(',',':')).encode();assert D(G(b))==b\\n  events+=[str(G(b))];k+=1\\n return {'system':'UTM-PLEIADES/v0.1','status':status,'steps':k,'bound':N,'state':s,'head':p,'tape':sorted(t.items()),'chronon_codes':events,'cycle':cycle,'godel_roundtrip':True,'physical_chronon_proven':False}\\ntry:\\n a=json.load(open(sys.argv[1])) if len(sys.argv)>1 else {'start':'q','halt':['H'],'input':'111','rules':[['q','1','q','X',1],['q','_','H','_',0]]}\\n N=int(sys.argv[2]) if len(sys.argv)>2 else 20\\n print(json.dumps(run(a,N),separators=(',',':')))\\nexcept Exception as e:print(json.dumps({'system':'UTM-PLEIADES/v0.1','status':'INVALID','reason':str(e)},separators=(',',':')))\")" "$@"
